create table if not exists public.bsc_gamagori_chart_ratings (race_date date not null, race_no smallint not null check (race_no between 1 and 12), boat_no smallint not null check (boat_no between 1 and 6), slit_rating smallint not null check (slit_rating between 1 and 5), turn_rating smallint not null check (turn_rating between 1 and 5), source_url text not null, captured_at timestamptz not null default now(), primary key (race_date,race_no,boat_no)); alter table public.bsc_gamagori_chart_ratings enable row level security; revoke all on public.bsc_gamagori_chart_ratings from anon,authenticated; comment on table public.bsc_gamagori_chart_ratings is 'Gamagori official evaluation chart extracted from HTML table; 6 boats per race completeness required for analysis.';